<?php
$pageTitle='Dashboard'; require __DIR__.'/../includes/admin_header.php';
$metrics=[]; foreach(['courses'=>'Cursos','classes'=>'Turmas','professors'=>'Professores','activities'=>'Atividades','materials'=>'Materiais','events'=>'Eventos','students'=>'Alunos'] as $t=>$l){ try{$metrics[] = [$l,(int)db()->query("SELECT COUNT(*) FROM {$t}")->fetchColumn()];}catch(Throwable $e){$metrics[]=[$l,0];}}
?>
<div class="top"><div class="title"><h1>Dashboard</h1><p>Bem-vindo, <?=e(current_user_name())?>.</p></div><a class="btn" href="<?=e(base_path('admin/crud.php?e=activities&action=new'))?>">+ Nova atividade</a></div><?php render_flash();?><div class="cards"><?php foreach($metrics as [$l,$v]):?><div class="card"><div class="muted"><?=e($l)?></div><div class="metric"><?=e($v)?></div></div><?php endforeach;?></div><br><div class="card"><h2>Próximas atividades</h2><?php $rows=db()->query("SELECT title,due_date FROM activities WHERE due_date IS NOT NULL AND due_date>=CURRENT_DATE ORDER BY due_date LIMIT 8")->fetchAll(); if(!$rows):?><p class="muted">Nenhuma atividade futura cadastrada.</p><?php else:?><table><tr><th>Atividade</th><th>Prazo</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e(date('d/m/Y',strtotime($r['due_date'])))?></td></tr><?php endforeach;?></table><?php endif;?></div>
<?php require __DIR__.'/../includes/admin_footer.php';?>
